import{at as e,it as t,n,vt as r}from"./chunks/framework.CinQa4et.js";import"./chunks/assets.BFXjnKeG.js";var i=JSON.parse(`{"title":"施策を作成・配信する","description":"","frontmatter":{},"headers":[],"relativePath":"guides/campaigns.md","filePath":"guides/campaigns.md","lastUpdated":1793464466000}`),a={name:`guides/campaigns.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="施策を作成・配信する" tabindex="-1">施策を作成・配信する <a class="header-anchor" href="#施策を作成・配信する" aria-label="Permalink to “施策を作成・配信する”">​</a></h1><p>「施策一覧」で、停止中・下書きを含む施策を確認できます。「新しい施策」から、対象者、表示内容、配信設定の順に設定します。編集者以上の権限が必要です。</p><h2 id="_1-施策名を付ける" tabindex="-1">1. 施策名を付ける <a class="header-anchor" href="#_1-施策名を付ける" aria-label="Permalink to “1. 施策名を付ける”">​</a></h2><p>施策名は管理用です。サイト上の「表示タイトル」とは別です。例として「夏のポロシャツ特集」と付けます。</p><h2 id="_2-案内する内容と対象者を入力する" tabindex="-1">2. 案内する内容と対象者を入力する <a class="header-anchor" href="#_2-案内する内容と対象者を入力する" aria-label="Permalink to “2. 案内する内容と対象者を入力する”">​</a></h2><p><strong>何を伝えたいですか？</strong>には、案内する内容を書きます。</p><blockquote><p>吸汗速乾ポロシャツの特集を案内する</p></blockquote><p><strong>どんな関心・状態に当てはまる人ですか？</strong>には、判断したい1つの関心・状態を書きます。</p><blockquote><p>吸汗速乾機能のあるポロシャツに関心がある</p></blockquote><p>どちらも各400文字以内です。商品画像や表示用HTMLではなく、判定の文脈を説明します。</p><h2 id="_3-実際の質問を確認する" tabindex="-1">3. 実際の質問を確認する <a class="header-anchor" href="#_3-実際の質問を確認する" aria-label="Permalink to “3. 実際の質問を確認する”">​</a></h2><p>入力を固定の型に当てはめて表示します。生成AIによる文章変換は行いません。</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>今回案内する内容：吸汗速乾ポロシャツの特集を案内する</span></span>
<span class="line"><span>閲覧履歴と連携された行動・状態の情報に基づき、この閲覧者に「吸汗速乾機能のあるポロシャツに関心がある」が当てはまりますか？</span></span></code></pre></div><p>意図に合わない場合は入力文を修正します。漠然とした「よさそうな人」「買ってくれそう」ではなく、何に関心があるか、どんな状態を判断したいかを書いてください。</p><table tabindex="0"><thead><tr><th>分野</th><th>案内する内容</th><th>判定する関心・状態</th></tr></thead><tbody><tr><td>BtoB</td><td>顧客情報共有の導入ガイド</td><td>複数部門での情報共有に課題がある</td></tr><tr><td>メディア</td><td>省エネ対策の記事特集</td><td>家庭向けの省エネ対策に関心がある</td></tr><tr><td>採用</td><td>開発組織の説明会</td><td>エンジニアの開発環境に関心がある</td></tr><tr><td>教育</td><td>初学者向け説明会</td><td>初心者向けの学習計画に関心がある</td></tr></tbody></table><h2 id="複数の条件" tabindex="-1">複数の条件 <a class="header-anchor" href="#複数の条件" aria-label="Permalink to “複数の条件”">​</a></h2><p>「判定する関心・状態を追加」で分けます。1問につき1つの判断を聞き、別の質問の回答は参照しません。</p><ul><li>AND：すべての質問が条件を満たす場合。</li><li>OR：いずれかの質問が条件を満たす場合。</li></ul><p>ページの完全一致や表示回数、応募済み等の確定状態は、質問へ埋め込まず配信設定で扱います。</p><p>閾値は0.5〜0.99です。判定値が設定値を<strong>上回る</strong>場合に対象とします。たとえば閾値0.70で判定値がちょうど0.70なら対象になりません。購入率・施策効果の予測値ではありません。</p><h2 id="_4-表示コンテンツを用意する" tabindex="-1">4. 表示コンテンツを用意する <a class="header-anchor" href="#_4-表示コンテンツを用意する" aria-label="Permalink to “4. 表示コンテンツを用意する”">​</a></h2><p>形式を選び、表示タイトル・メッセージ・ボタン・リンク・画像を設定します。<a href="./presentation">表示形式</a>に詳細をまとめています。</p><p><img src="/jev-personalization/images/campaign.png" alt="施策の表示コンテンツ" width="1440" height="1384"></p><h2 id="_5-配信設定" tabindex="-1">5. 配信設定 <a class="header-anchor" href="#_5-配信設定" aria-label="Permalink to “5. 配信設定”">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>意味</th></tr></thead><tbody><tr><td>表示するページ</td><td>全許可ページ、完全一致、前方一致。パスで指定</td></tr><tr><td>表示回数の上限</td><td>ブラウザの有効な履歴内の上限</td></tr><tr><td>優先順位</td><td>複数対象の場合、大きい値を優先</td></tr><tr><td>除外する確定状態</td><td>登録済みfactがtrueなら除外</td></tr></tbody></table><p>除外状態を指定した場合、値が不明なまま対象とは扱いません。未完了ならfalse、完了したらtrueを<a href="./../integration/sdk">SDK</a>から明示して連携します。</p><h2 id="_6-下書き保存と配信開始" tabindex="-1">6. 下書き保存と配信開始 <a class="header-anchor" href="#_6-下書き保存と配信開始" aria-label="Permalink to “6. 下書き保存と配信開始”">​</a></h2><p><strong>下書き保存</strong>では、編集中の内容を保存します。公開中の施策を編集しても、以前の配信内容は維持します。途中の入力も保存できます。</p><p><strong>配信内容を確認 → この内容で配信開始</strong>で公開設定へ反映します。未入力の判定条件や表示タイトルがあれば開始できません。</p><p>配信前は一覧の<a href="./testing">プレビュー</a>から実ページで確認してください。停止・再開は一覧から行います。</p><h2 id="同時編集で競合した場合" tabindex="-1">同時編集で競合した場合 <a class="header-anchor" href="#同時編集で競合した場合" aria-label="Permalink to “同時編集で競合した場合”">​</a></h2><p>別の変更を上書きしないよう、古い編集は保存・配信を拒否します。一覧を読み直し、最新の内容を確認します。必要な入力を控えたうえで下書きを破棄し、最新内容から編集し直してください。</p><p>既存の手動質問は保持します。「入力支援に切り替える」を選んだときだけ新しい入力方法へ変更します。</p>`,33)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};